import pytest

def test_exception_on_empty_data_with_maxcolwidths():
    from tabulate import tabulate
    try:
        result = tabulate([], maxcolwidths=5)
    except IndexError:
        assert False, "IndexError raised when tabulating empty data with maxcolwidths"
    assert result == ""

